import java.nio.*;
import java.nio.file.*;
import java.util.*;
import com.google.gson.*;
import org.lwjgl.glfw.GLFW;
import org.lwjgl.opengl.*;
import com.iridium126.createmanaindustry.client.particles.engine.hardware.HardwareNative;

/** Exercises the real shared-pointer worker; no map/unmap or CUDA sync on caller. */
public final class R7AsyncGpu extends ModelPopulationGpuValidation {
    static int align(int n){return (n+255)&~255;}
    static int waitResult(long worker,int slot,long nonce){long deadline=System.nanoTime()+10_000_000_000L;for(;;){int state=HardwareNative.pollAsyncQuery(worker,slot,nonce);if(state!=1)return state;check(System.nanoTime()<deadline,"bounded worker completion");if((Integer.getInteger("cmi.r8.policy",0)&2)!=0)HardwareNative.waitAsyncQuery(worker,slot,nonce,50);else java.util.concurrent.locks.LockSupport.parkNanos(100_000);}}
    static ByteBuffer packet(int n,int q,long nonce,long epoch,float[] points){int requests=align(64+n*16),owners=align(requests+q*16),map=align(owners+q*4);var p=bytes(map+n*4);p.putInt(0,0x52374931).putInt(4,1).putLong(8,nonce).putInt(16,n).putInt(20,q).putFloat(28,1).putInt(32,64).putInt(36,requests).putInt(40,owners).putInt(44,map).putInt(48,n).putLong(56,epoch);for(int i=0;i<n;i++){for(int k=0;k<4;k++)p.putFloat(64+i*16+k*4,points[i*4+k]);p.putInt(map+i*4,n-1-i);}for(int i=0;i<q;i++){for(int k=0;k<3;k++)p.putFloat(requests+i*16+k*4,points[i*4+k]);p.putFloat(requests+i*16+12,1);p.putInt(owners+i*4,i);}return p;}
    public static void main(String[] args)throws Exception{
        Path out=Path.of(System.getProperty("cmi.benchmark.output"));Files.createDirectories(out);check(!Files.exists(out.resolve("async.json")),"fresh output");Path source=out.resolve("source");Files.createDirectory(source);for(String name:List.of("Query.h","grid.cu","rt.cu","rt-triangle.cu","tensor.cu"))Files.copy(Path.of("native/offload",name),source.resolve(name));var deps=JsonParser.parseString(Files.readString(Path.of(".gradle/neighbor-rt/dependencies.json"))).getAsJsonObject();
        check(GLFW.glfwInit(),"GLFW");GLFW.glfwWindowHint(GLFW.GLFW_VISIBLE,0);GLFW.glfwWindowHint(GLFW.GLFW_CONTEXT_VERSION_MAJOR,4);GLFW.glfwWindowHint(GLFW.GLFW_CONTEXT_VERSION_MINOR,6);long window=GLFW.glfwCreateWindow(32,32,"R7 async query worker",0,0);check(window!=0,"GL context");GLFW.glfwMakeContextCurrent(window);GL.createCapabilities();HardwareNative.load(Path.of(".gradle/hardware-offload/build"));
        long bridge=HardwareNative.createCopy(8*1024*1024,3),worker=0;var metadata=new LinkedHashMap<String,Object>();metadata.put("passed",false);var cases=new ArrayList<Object>();
        try{
            worker=HardwareNative.createAsyncQuery(bridge,1000,1000,(8*1024*1024-64-align(16+1001*8))/4,91,deps.getAsJsonObject("cuda_cudart").get("root").getAsString(),deps.getAsJsonObject("optix").get("root").getAsString(),source.toAbsolutePath().toString(),deps.getAsJsonObject("cuda_nvcc").get("root").getAsString());
            HardwareNative.configureAsyncQuery(worker,Integer.getInteger("cmi.r8.policy",0),64<<20);boolean nonceRefused=false;try{HardwareNative.waitAsyncQuery(worker,0,99,0);}catch(IllegalStateException expected){nonceRefused=true;}check(nonceRefused,"event wait rejects stale nonce");
            long bad=HardwareNative.createAsyncQueryForBackend(bridge,65,65,4096,91,0,deps.getAsJsonObject("cuda_cudart").get("root").getAsString(),deps.getAsJsonObject("optix").get("root").getAsString(),source.toAbsolutePath().toString(),deps.getAsJsonObject("cuda_nvcc").get("root").getAsString());boolean invalidPage=false;try{HardwareNative.configureAsyncQuery(bad,4,143);}catch(IllegalStateException expected){invalidPage=true;}check(invalidPage&&!HardwareNative.submitAsyncQuery(bad,0,100,0,false),"failed paging configuration cannot submit partial resources");long closeDeadline=System.nanoTime()+5_000_000_000L;while(!HardwareNative.closeAsyncQuery(bad)){check(System.nanoTime()<closeDeadline,"failed configure retires");Thread.sleep(1);}
            long beforeFailedInit=JsonParser.parseString(HardwareNative.probe()).getAsJsonObject().get("native_owned_bytes").getAsLong();boolean initRefused=false;try{HardwareNative.createAsyncQueryForBackend(bridge,65,65,4096,91,0,deps.getAsJsonObject("cuda_cudart").get("root").getAsString(),deps.getAsJsonObject("optix").get("root").getAsString(),source.resolve("missing-source").toAbsolutePath().toString(),deps.getAsJsonObject("cuda_nvcc").get("root").getAsString());}catch(IllegalStateException expected){initRefused=true;}check(initRefused,"missing native source rejects initialization");check(JsonParser.parseString(HardwareNative.probe()).getAsJsonObject().get("native_owned_bytes").getAsLong()==beforeFailedInit,"failed initialization releases owned buffers and bridge lease");metadata.put("initialization_failure_test",true);boolean leased=false;try{HardwareNative.closeCopy(bridge);}catch(IllegalStateException expected){leased=true;}check(leased,"leased ring cannot be destroyed");
            for(int backend=0;backend<5;backend++){
                for(int slot=0;slot<3;slot++){int n=slot==0?65:slot==1?257:1000,q=Math.min(n,128);float[] points=NeighborQueryGpuValidation.positions(n,"crowded");long nonce=100+backend*3+slot;int[] ids=HardwareNative.copyBuffers(bridge,slot);put(ids[0],packet(n,q,nonce,91,points));check(HardwareNative.submitAsyncQuery(worker,slot,nonce,backend,false),"bounded submit");check(!HardwareNative.submitAsyncQuery(worker,slot,nonce+1000,backend,false),"no in-flight overwrite");}
                for(int slot=0;slot<3;slot++){int n=slot==0?65:slot==1?257:1000,q=Math.min(n,128);long nonce=100+backend*3+slot;int state=waitResult(worker,slot,nonce);check(state==2,"worker ready: "+HardwareNative.asyncQueryError(worker,slot,nonce));HardwareNative.consumeAsyncQuery(worker,slot,nonce);int[] buffers=HardwareNative.copyBuffers(bridge,slot);ByteBuffer result=R7HardwareGpu.readShared(buffers[1],8*1024*1024);check(result.getLong(4)==nonce&&result.getLong(40)==91,"result frame/resource envelope");check(result.getInt(36)==1&&result.getInt(32)==0,"complete result");int ids=result.getInt(24),total=0;var expected=NeighborQueryGpuValidation.reference(NeighborQueryGpuValidation.positions(n,"crowded"),q,1);
                    for(int i=0;i<q;i++){long from=result.getLong(80+i*8),to=result.getLong(88+i*8);check(from==total&&to>=from,"CSR coverage");int[] row=new int[(int)(to-from)];for(int k=0;k<row.length;k++)row[k]=result.getInt((ids+(int)from+k)*4);Arrays.sort(row);int[] reference=Arrays.stream(expected[i]).map(j->n-1-j).sorted().toArray();check(Arrays.equals(row,reference),"mapped complete candidates");total=(int)to;}check(result.getLong(64)==total,"total");double[] timing=HardwareNative.asyncQueryTiming(worker,slot,nonce);check(!HardwareNative.recycleAsyncQuery(worker,slot,nonce,0),"consumer needs retirement fence");long fence=GL32.glFenceSync(GL32.GL_SYNC_GPU_COMMANDS_COMPLETE,0);GL11.glFlush();while(!HardwareNative.recycleAsyncQuery(worker,slot,nonce,fence))java.util.concurrent.locks.LockSupport.parkNanos(100_000);GL32.glDeleteSync(fence);cases.add(Map.of("backend",backend,"points",n,"queries",q,"timing_ms",timing,"lifetime_trace",HardwareNative.asyncQueryTrace(worker,slot,nonce)));
                }
            }
            float[] points=NeighborQueryGpuValidation.positions(65,"crowded");int[] ids=HardwareNative.copyBuffers(bridge,0);put(ids[0],packet(65,65,900,92,points));check(HardwareNative.submitAsyncQuery(worker,0,900,1,false),"invalid epoch queued");check(waitResult(worker,0,900)==3,"invalid epoch selects retired fallback");boolean refused=false;try{HardwareNative.consumeAsyncQuery(worker,0,900);}catch(IllegalStateException expected){refused=true;}check(refused,"failed output cannot be consumed");check(HardwareNative.recycleAsyncQuery(worker,0,900,0),"failed read-only packet retired");
            HardwareNative.injectAsyncQueryDelay(worker,500,50);put(ids[0],packet(65,65,901,91,points));check(HardwareNative.submitAsyncQuery(worker,0,901,1,false),"bounded timeout injection queued");check(waitResult(worker,0,901)==4,"timeout quarantines resources");check(!HardwareNative.closeAsyncQuery(worker),"unretired GPU callback cannot be freed");
            check(GL11.glGetError()==0,"GL state");metadata.put("passed",true);metadata.put("timeout_quarantine_test",true);
        }finally{
            if(worker!=0){long deadline=System.nanoTime()+5_000_000_000L;while(!HardwareNative.closeAsyncQuery(worker)){check(System.nanoTime()<deadline,"worker close remains bounded");java.util.concurrent.locks.LockSupport.parkNanos(100_000);}}
            HardwareNative.closeCopy(bridge);var retired=JsonParser.parseString(HardwareNative.probe()).getAsJsonObject();check(retired.get("native_owned_bytes").getAsLong()==0,"all explicit native buffers retired");metadata.put("after_retirement",retired);metadata.put("checks",checks);metadata.put("cases",cases);Files.writeString(out.resolve("async.json"),new GsonBuilder().setPrettyPrinting().create().toJson(metadata)+"\n");GLFW.glfwDestroyWindow(window);GLFW.glfwTerminate();
        }
    }
}
